// WOLFICH COD — уведомления в Telegram на Cloudflare Workers + D1.
// Один файл. Привязки: DB (D1). Переменные: BOT_TOKEN, SECRET, ALLOWED_ORIGIN, PUBLIC_URL, GOOGLE_CLIENT_ID (вход через Google).
// Аккаунты: старые — uid = id Telegram; через Google — uid = g<sub>. Способы входа одного аккаунта — таблица idents (t:<id>, g:<sub>).
const enc = new TextEncoder();
const hex = (buf) => Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
async function hmacHex(key, data) {
  const k = await crypto.subtle.importKey("raw", typeof key === "string" ? enc.encode(key) : key, { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return hex(await crypto.subtle.sign("HMAC", k, enc.encode(data)));
}
function eq(a, b) {
  a = String(a); b = String(b);
  if (a.length !== b.length) return false;
  let d = 0;
  for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return d === 0;
}
const nowOf = (env) => (typeof env.__now === "function" ? env.__now() : Date.now());

async function tg(env, method, body) {
  const base = env.TG_API || "https://api.telegram.org";
  const r = await fetch(base + "/bot" + env.BOT_TOKEN + "/" + method, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
  let j = {}; try { j = await r.json(); } catch (e) {}
  return { ok: !!j.ok, code: j.error_code || r.status };
}
const send = (env, chat, text) => tg(env, "sendMessage", { chat_id: Number(chat), text: text, disable_web_page_preview: true });
// мини-приложение «Альянс» (сайт в режиме Telegram): кнопка меню чата и кнопка под сообщением
const allyUrl = (env) => env.ALLY_URL || "https://wolfichxxx.github.io/CODWOLFICH/?tgapp=1&v=2#ally";
const allyKb = (env, lang) => ({ inline_keyboard: [[{ text: lang === "en" ? "🛡 Open Alliance" : "🛡 Открыть альянс", web_app: { url: allyUrl(env) } }]] });
const allyMenu = (env, chat, lang) => tg(env, "setChatMenuButton", { chat_id: Number(chat), menu_button: { type: "web_app", text: lang === "en" ? "Alliance" : "Альянс", web_app: { url: allyUrl(env) } } });
const sendAlly = (env, chat, text, lang) => tg(env, "sendMessage", { chat_id: Number(chat), text: text, disable_web_page_preview: true, reply_markup: allyKb(env, lang) });

// ---------- стикеры (w — приветствие при входе через бота, b — стройка, r — исследование, t — обучение, c — ОУ, m — заслуги, g — общее напоминание) ----------
const STICKERS = {"w": "", "g": "", "m": "", "c": "", "t": "", "r": "", "b": ""};
// текст из калькулятора: «#b|Строка» — буква выбирает стикер
function parseText(t) { const m = /^#([a-z])\|([\s\S]*)$/.exec(String(t || "")); return m ? { icon: m[1], body: m[2] } : { icon: "", body: String(t || "") }; }
function b64bytes(b64) { const bin = atob(b64); const u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i); return u; }
const STICKERS_EN = {"w": "", "g": "", "t": "", "r": "", "c": "", "b": "", "m": ""};   // английские стикеры
async function sendSticker(env, chat, key, lang) {
  const base = env.TG_API || "https://api.telegram.org";
  const fd = new FormData();
  fd.append("chat_id", String(Number(chat)));
  const en = lang === "en", src = en ? (STICKERS_EN[key] || STICKERS_EN.g) : STICKERS[key];
  fd.append("sticker", new Blob([b64bytes(src)], { type: "image/webp" }), key + ".webp");
  const r = await fetch(base + "/bot" + env.BOT_TOKEN + "/sendSticker", { method: "POST", body: fd });
  let j = {}; try { j = await r.json(); } catch (e) {}
  return { ok: !!j.ok, code: j.error_code || r.status };
}
async function sendNote(env, chat, text, lang) {
  const p = parseText(text);
  if (p.icon && STICKERS[p.icon]) { const r = await sendSticker(env, chat, p.icon, lang); if (!r.ok && r.code === 403) return r; }
  return send(env, chat, p.body);
}

// ---------- база ----------
const SCHEMA = [
  "CREATE TABLE IF NOT EXISTS users (uid TEXT PRIMARY KEY, name TEXT, created INTEGER, blocked INTEGER DEFAULT 0)",
  "CREATE TABLE IF NOT EXISTS items (uid TEXT NOT NULL, key TEXT NOT NULL, at INTEGER NOT NULL, text TEXT NOT NULL, sent INTEGER DEFAULT 0, sent_at INTEGER, PRIMARY KEY (uid, key))",
  "CREATE INDEX IF NOT EXISTS items_due ON items (sent, at)",
  "CREATE TABLE IF NOT EXISTS logins (code TEXT PRIMARY KEY, uid TEXT NOT NULL, name TEXT, at INTEGER NOT NULL)",
  "CREATE TABLE IF NOT EXISTS profiles (uid TEXT PRIMARY KEY, data TEXT NOT NULL, ver INTEGER NOT NULL, updated INTEGER NOT NULL)",
  // аккаунты: способ входа → аккаунт. t:<id Telegram> / g:<sub Google>. Старые аккаунты Telegram — uid = id Telegram (строки может не быть)
  "CREATE TABLE IF NOT EXISTS idents (ext TEXT PRIMARY KEY, uid TEXT NOT NULL, at INTEGER NOT NULL)",
  "CREATE INDEX IF NOT EXISTS idents_uid ON idents (uid)",
  // привязка Telegram к уже открытому аккаунту: сайт создаёт код, человек жмёт «Старт» у бота
  "CREATE TABLE IF NOT EXISTS links (code TEXT PRIMARY KEY, uid TEXT NOT NULL, st TEXT, at INTEGER NOT NULL)",
  // кто сейчас смотрит карту планера: комната a:<альянс>:<команда> / p:<планер>, отметка раз в ~45 с
  "CREATE TABLE IF NOT EXISTS presence (room TEXT NOT NULL, uid TEXT NOT NULL, name TEXT, at INTEGER NOT NULL, PRIMARY KEY (room, uid))",
  // чат на карте планера (та же комната), хранится 7 дней
  "CREATE TABLE IF NOT EXISTS chat (id INTEGER PRIMARY KEY AUTOINCREMENT, room TEXT NOT NULL, uid TEXT NOT NULL, name TEXT, text TEXT NOT NULL, at INTEGER NOT NULL)",
  "CREATE INDEX IF NOT EXISTS chat_room ON chat (room, id)",
  // кэш автоперевода: h = sha256(язык|текст)
  "CREATE TABLE IF NOT EXISTS trc (h TEXT PRIMARY KEY, out TEXT NOT NULL, src TEXT, at INTEGER NOT NULL)",
];
/* автоперевод: Google (без ключа, язык исходника определяется сам); запасной — Workers AI (привязка AI), если подключена */
async function sha256Hex(s) { return Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s))), (x) => x.toString(16).padStart(2, "0")).join(""); }
const TR_UA = { "user-agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36", accept: "application/json,text/plain,*/*" };
const TR_LANG = { ru: "Russian", en: "English", uk: "Ukrainian", be: "Belarusian", kk: "Kazakh", de: "German", fr: "French", es: "Spanish", it: "Italian", pt: "Portuguese", pl: "Polish", tr: "Turkish", ar: "Arabic", "zh-CN": "Simplified Chinese", "zh-TW": "Traditional Chinese", zh: "Chinese", ja: "Japanese", ko: "Korean", vi: "Vietnamese", id: "Indonesian", th: "Thai" };
const TRP = {   // переводчики по очереди: первый ответивший — победил
  async gtx(text, to) {
    const r = await fetch("https://translate.googleapis.com/translate_a/single?client=gtx&dt=t&sl=auto&tl=" + encodeURIComponent(to) + "&q=" + encodeURIComponent(text), { headers: TR_UA });
    if (!r.ok) throw new Error("HTTP " + r.status); const j = await r.json();
    const out = (j[0] || []).map((x) => (x && x[0]) || "").join(""); if (!out) throw new Error("empty"); return { out, src: String(j[2] || "") };
  },
  async dict(text, to) {
    const r = await fetch("https://clients5.google.com/translate_a/t?client=dict-chrome-ex&sl=auto&tl=" + encodeURIComponent(to) + "&q=" + encodeURIComponent(text), { headers: TR_UA });
    if (!r.ok) throw new Error("HTTP " + r.status); const j = await r.json();
    if (Array.isArray(j)) { const x = j[0]; if (Array.isArray(x) && x[0]) return { out: String(x[0]), src: String(x[1] || "") }; if (typeof x === "string" && x) return { out: x, src: "" }; }
    if (j && j.sentences) { const out = j.sentences.map((x) => x.trans || "").join(""); if (out) return { out, src: String(j.src || "") }; }
    throw new Error("empty");
  },
  async mym(text, to) {
    const r = await fetch("https://api.mymemory.translated.net/get?q=" + encodeURIComponent(text) + "&langpair=" + encodeURIComponent("Autodetect|" + to), { headers: TR_UA });
    if (!r.ok) throw new Error("HTTP " + r.status); const j = await r.json();
    const out = j && j.responseData && j.responseData.translatedText; if (!out || +j.responseStatus !== 200) throw new Error("status " + (j && j.responseStatus) + " " + String((j && j.responseDetails) || "").slice(0, 80));
    let src = String((j.responseData && j.responseData.detectedLanguage) || ""); if (!src && Array.isArray(j.matches) && j.matches[0]) src = String(j.matches[0].source || "");
    return { out: String(out), src: src.split("-")[0] };
  },
  async ai(text, to, env) {   // Workers AI (привязка AI, бесплатно 10 000 нейронов в день): языковая модель сама определяет язык оригинала
    if (!env.AI) throw new Error("нет привязки AI");
    const base = to.split("-")[0], name = TR_LANG[to] || TR_LANG[base] || to;
    try {
      const r = await env.AI.run("@cf/meta/llama-3.1-8b-instruct-fp8-fast", { temperature: 0, max_tokens: 600, messages: [
        { role: "system", content: "You are a translation engine for the mobile strategy game Call of Dragons. Translate the user's message into " + name + ". Detect the source language yourself. Keep nicknames, alliance tags, numbers, times and emoji unchanged. If the message is already in " + name + ", return it unchanged. Answer ONLY with JSON: {\"src\":\"<ISO 639-1 code of the source language>\",\"t\":\"<translation>\"}" },
        { role: "user", content: text }] });
      let o = r && r.response; if (typeof o === "string") { const m = /\{[\s\S]*\}/.exec(o); try { o = m ? JSON.parse(m[0]) : null; } catch (e) { o = null; } }
      if (o && typeof o.t === "string" && o.t.trim()) return { out: o.t.trim(), src: String(o.src || "").toLowerCase().slice(0, 5) };
    } catch (e) { /* модель недоступна — простой переводчик ниже */ }
    const src = /[\u0400-\u04ff]/.test(text) ? "ru" : "en"; if (src === base) return { out: text, src };
    const r = await env.AI.run("@cf/meta/m2m100-1.2b", { text, source_lang: src, target_lang: base });
    if (!r || !r.translated_text) throw new Error("empty"); return { out: r.translated_text, src };
  },
};
async function trOne(env, text, to, log) {
  for (const k of ["dict", "gtx", "ai", "mym"]) {
    try { const r = await TRP[k](text, to, env); if (log) log[k] = "ok: " + r.out + " (" + r.src + ")"; else return r; }
    catch (e) { if (log) log[k] = "ошибка: " + String((e && e.message) || e).slice(0, 120); }
  }
  return null;
}
let schemaReady = false;   // таблицы создаются сами при первом обращении — повторно запускать setup не нужно
async function ensureSchema(env) { if (schemaReady) return; await env.DB.batch(SCHEMA.map((q) => env.DB.prepare(q))); schemaReady = true; }
const PROFILE_MAX = 1500000;   // символов JSON на один профиль (лимит строки D1 — 2 МБ)
const db = {
  getUser: (env, uid) => env.DB.prepare("SELECT uid, name, created, blocked FROM users WHERE uid = ?").bind(uid).first(),
  putUser: (env, u) => env.DB.prepare("INSERT INTO users (uid, name, created, blocked) VALUES (?, ?, ?, ?) ON CONFLICT(uid) DO UPDATE SET name = excluded.name, blocked = excluded.blocked").bind(u.uid, u.name, u.created, u.blocked ? 1 : 0).run(),
  listItems: async (env, uid) => (await env.DB.prepare("SELECT key, at, text, sent FROM items WHERE uid = ?").bind(uid).all()).results || [],
  putItem: (env, uid, it) => env.DB.prepare("INSERT OR REPLACE INTO items (uid, key, at, text, sent, sent_at) VALUES (?, ?, ?, ?, ?, NULL)").bind(uid, it.key, it.at, it.text, it.sent ? 1 : 0).run(),
  delItem: (env, uid, key) => env.DB.prepare("DELETE FROM items WHERE uid = ? AND key = ?").bind(uid, key).run(),
  getProfile: (env, uid) => env.DB.prepare("SELECT data, ver, updated FROM profiles WHERE uid = ?").bind(uid).first(),
  putProfile: (env, uid, data, ver, now) => env.DB.prepare("INSERT INTO profiles (uid, data, ver, updated) VALUES (?, ?, ?, ?) ON CONFLICT(uid) DO UPDATE SET data = excluded.data, ver = excluded.ver, updated = excluded.updated").bind(uid, data, ver, now).run(),
  delProfile: (env, uid) => env.DB.prepare("DELETE FROM profiles WHERE uid = ?").bind(uid).run(),
  deleteUser: (env, uid) => env.DB.batch([env.DB.prepare("DELETE FROM items WHERE uid = ?").bind(uid), env.DB.prepare("DELETE FROM users WHERE uid = ?").bind(uid)]),
};

const TOKEN_TTL = 180 * 86400000;   // вход держится полгода
// способ входа → аккаунт. Строка idents с uid "!" — способ отвязан: следующий вход создаст новый аккаунт
const newUid = () => { const a = new Uint8Array(15); crypto.getRandomValues(a); return "g9" + Array.from(a, (b) => String(b % 100).padStart(2, "0")).join(""); };
async function resolveAcct(env, ext, derived, create) {
  const r = await env.DB.prepare("SELECT uid FROM idents WHERE ext = ?").bind(ext).first();
  if (r && r.uid !== "!") return r.uid;
  if (!r) return derived;
  if (!create) return "";
  const nu = newUid(); await env.DB.prepare("UPDATE idents SET uid = ?, at = ? WHERE ext = ?").bind(nu, nowOf(env), ext).run(); return nu;
}
const acctOfTg = (env, tg, create) => resolveAcct(env, "t:" + tg, String(tg), create !== false);
async function tgOwnLegacy(env, uid) {   // старый аккаунт Telegram (uid = id Telegram): Telegram всё ещё его?
  if (!/^\d+$/.test(uid)) return false;
  const r = await env.DB.prepare("SELECT uid FROM idents WHERE ext = ?").bind("t:" + uid).first();
  return !r || r.uid === uid;
}
async function chatOf(env, uid) {   // куда слать напоминания аккаунта: свой или привязанный Telegram
  if (await tgOwnLegacy(env, uid)) return uid;
  const r = await env.DB.prepare("SELECT ext FROM idents WHERE uid = ? AND ext LIKE 't:%'").bind(uid).first();
  return r ? r.ext.slice(2) : "";
}
async function identsOf(env, uid) {
  const rows = ((await env.DB.prepare("SELECT ext FROM idents WHERE uid = ?").bind(uid).all()).results) || [];
  return { tg: (await tgOwnLegacy(env, uid)) || rows.some((x) => x.ext.slice(0, 2) === "t:"), google: rows.some((x) => x.ext.slice(0, 2) === "g:") };
}
async function moveInto(env, from, to) {   // перенос способа входа: напоминания — в новый аккаунт, профиль — если в новом пусто
  if (!from || from === to) return;
  await env.DB.prepare("UPDATE OR IGNORE items SET uid = ? WHERE uid = ?").bind(to, from).run();
  for (const pre of ["", "r"]) {
    const src = await db.getProfile(env, pre + from), dst = await db.getProfile(env, pre + to);
    if (src && !dst) await db.putProfile(env, pre + to, src.data, 1, nowOf(env));
  }
}
async function mkToken(env, uid, now) { const exp = now + TOKEN_TTL; return uid + "." + exp + "." + (await hmacHex(env.SECRET || "", uid + "." + exp)); }

// ---------- Google: проверка ID-токена (Google Identity Services) ----------
let gKeys = null, gKeysAt = 0;
const b64u = (s) => { s = String(s).replace(/-/g, "+").replace(/_/g, "/"); while (s.length % 4) s += "="; return b64bytes(s); };
async function googleVerify(env, cred) {
  const parts = String(cred || "").split("."); if (parts.length !== 3) return null;
  let head, pl; try { head = JSON.parse(new TextDecoder().decode(b64u(parts[0]))); pl = JSON.parse(new TextDecoder().decode(b64u(parts[1]))); } catch (e) { return null; }
  if (head.alg !== "RS256" || !head.kid) return null;
  const now = nowOf(env);
  if (!gKeys || now - gKeysAt > 3600000 || !gKeys.some((k) => k.kid === head.kid)) {
    const r = await fetch(env.GOOGLE_CERTS || "https://www.googleapis.com/oauth2/v3/certs"); const j = await r.json(); gKeys = (j && j.keys) || []; gKeysAt = now;
  }
  const jwk = gKeys.find((k) => k.kid === head.kid); if (!jwk) return null;
  const key = await crypto.subtle.importKey("jwk", { kty: "RSA", n: jwk.n, e: jwk.e, alg: "RS256", ext: true }, { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" }, false, ["verify"]);
  const ok = await crypto.subtle.verify("RSASSA-PKCS1-v1_5", key, b64u(parts[2]), enc.encode(parts[0] + "." + parts[1]));
  if (!ok) return null;
  const ids = String(env.GOOGLE_CLIENT_ID || "").split(",").map((x) => x.trim()).filter(Boolean);
  if (!ids.includes(pl.aud)) return null;
  if (pl.iss !== "accounts.google.com" && pl.iss !== "https://accounts.google.com") return null;
  if (!(Number(pl.exp) * 1000 > now) || !/^\d{1,40}$/.test(String(pl.sub || ""))) return null;
  return { sub: String(pl.sub), name: String(pl.given_name || pl.name || "игрок").slice(0, 60) };
}

// ---------- язык бота: ru или en ----------
// Хранится в profiles под ключом "l"+uid (отдельная колонка не нужна). Сайт присылает lang в sync/test/auth — он главнее;
// language_code из Telegram используется, пока сайт язык не сообщил.
const RU_CODES = /^(ru|uk|be|kk|ky|uz|tg|hy|az|ka|mo)\b/i;
const tgLang = (code) => (code && !RU_CODES.test(String(code)) ? "en" : "ru");
async function getLang(env, uid) { try { const r = await env.DB.prepare("SELECT data FROM profiles WHERE uid = ?").bind("l" + uid).first(); return r && r.data === "en" ? "en" : "ru"; } catch (e) { return "ru"; } }
async function setLang(env, uid, lang, soft) {
  if (lang !== "en" && lang !== "ru") return;
  try {
    if (soft) { const r = await env.DB.prepare("SELECT 1 AS x FROM profiles WHERE uid = ?").bind("l" + uid).first(); if (r) return; }
    await env.DB.prepare("INSERT INTO profiles (uid, data, ver, updated) VALUES (?, ?, 1, ?) ON CONFLICT(uid) DO UPDATE SET data = excluded.data, updated = excluded.updated").bind("l" + uid, lang, Date.now()).run();
  } catch (e) {}
}
