// ---------- бот ----------
function leftTxt(ms, lang) { const T = TXT[lang === "en" ? "en" : "ru"]; const m = Math.max(0, Math.round(ms / 60000)); const d = Math.floor(m / 1440), h = Math.floor(m % 1440 / 60), mm = m % 60; return (d ? d + T.d : "") + (h ? h + T.h : "") + mm + T.m; }

async function onUpdate(env, u) {
  const m = u.message; if (!m || !m.chat || m.chat.type !== "private" || !m.from) return;
  const uid = String(m.from.id), t = String(m.text || "").trim(), lc = tgLang(m.from.language_code), cmd = (t.split(/[\s@]/)[0] || "").toLowerCase(), now = nowOf(env);
  // вход с сайта через бота: сайт открывает t.me/<бот>?start=login_<код>, человек жмёт «Старт», сайт забирает токен
  const lg = /^\/start(?:@\w+)?\s+login_([a-f0-9]{24,64})$/i.exec(t);
  if (lg) {
    await ensureSchema(env);
    const acct = await acctOfTg(env, uid, true);   // Telegram может быть привязан к аккаунту, созданному через Google (или отвязан — тогда новый аккаунт)
    const nm = String(m.from.first_name || m.from.username || "игрок").slice(0, 60), old = await db.getUser(env, acct);
    await db.putUser(env, { uid: acct, name: (old && acct !== uid && old.name) || nm, created: (old && old.created) || now, blocked: false });
    await env.DB.prepare("INSERT OR REPLACE INTO logins (code, uid, name, at) VALUES (?, ?, ?, ?)").bind(lg[1].toLowerCase(), acct, (old && acct !== uid && old.name) || nm, now).run();
    await setLang(env, acct, lc, true);
    try { await allyMenu(env, m.chat.id, await getLang(env, acct)); } catch (e) {}
    return sendNote(env, m.chat.id, TXT[await getLang(env, acct)].welcome, await getLang(env, acct));
  }
  const lk = /^\/start(?:@\w+)?\s+link_([a-f0-9]{24,64})$/i.exec(t);
  if (lk) {   // привязка этого Telegram к аккаунту, открытому на сайте (вошли через Google)
    await ensureSchema(env);
    const code = lk[1].toLowerCase(), row = await env.DB.prepare("SELECT uid, at FROM links WHERE code = ?").bind(code).first();
    const say = (ru, en) => send(env, m.chat.id, lc === "en" ? en : ru);
    if (!row || now - row.at > 900000) return say("Ссылка для привязки устарела. Нажмите «Привязать Telegram» на сайте ещё раз.", "The link has expired. Press “Link Telegram” on the site again.");
    const cur = await env.DB.prepare("SELECT uid FROM idents WHERE ext = ?").bind("t:" + uid).first();
    const other = cur ? (cur.uid !== "!" && cur.uid !== row.uid ? cur.uid : "") : (uid !== row.uid && (await db.getUser(env, uid)) ? uid : "");
    if (other) {   // у этого Telegram уже свой аккаунт — перенос подтверждают на сайте
      const ou = await db.getUser(env, other);
      await env.DB.prepare("UPDATE links SET st = ? WHERE code = ?").bind("conf:" + uid + ":" + String((ou && ou.name) || "").slice(0, 40), code).run();
      return say("Этот Telegram уже зарегистрирован на сайте отдельным аккаунтом. Вернитесь на сайт и подтвердите перенос.", "This Telegram is already registered on the site as a separate account. Go back to the site and confirm the move.");
    }
    await env.DB.prepare("INSERT OR REPLACE INTO idents (ext, uid, at) VALUES (?, ?, ?)").bind("t:" + uid, row.uid, now).run();
    await env.DB.prepare("UPDATE links SET st = 'ok' WHERE code = ?").bind(code).run();
    await setLang(env, row.uid, lc, true);
    return say("✅ Telegram привязан к вашему аккаунту WOLFICH. Входите на сайт как удобно — через Google или Telegram.", "✅ Telegram is linked to your WOLFICH account. Sign in to the site either way — Google or Telegram.");
  }
  await ensureSchema(env);
  const tgid = uid, acct = (await acctOfTg(env, tgid, false)) || "none:" + tgid;   // "none:" — Telegram отвязан и ещё не входил заново
  await setLang(env, acct, lc, true);
  const L = await getLang(env, acct), T = TXT[L];
  if (cmd === "/stop" || cmd === "/deleteme") {
    if (acct.slice(0, 5) === "none:") return send(env, m.chat.id, T.stop);
    if (acct !== tgid) { await env.DB.prepare("DELETE FROM items WHERE uid = ?").bind(acct).run(); await env.DB.prepare("DELETE FROM idents WHERE ext = ?").bind("t:" + tgid).run(); return send(env, m.chat.id, T.stop); }   // привязанный Telegram — отвязать
    await db.deleteUser(env, tgid); await db.delProfile(env, "l" + tgid); return send(env, m.chat.id, T.stop);
  }
  const usr = await db.getUser(env, acct);
  if (usr && usr.blocked) { await db.putUser(env, { uid: acct, name: usr.name, created: usr.created, blocked: false }); }
  if (cmd === "/list") {
    const its = (await db.listItems(env, acct)).filter((x) => !x.sent).sort((a, b) => a.at - b.at).slice(0, 15);
    if (!its.length) return send(env, m.chat.id, usr ? T.none : T.nologin + T.help);
    return send(env, m.chat.id, T.next + its.map((x) => T.in + leftTxt(x.at - now, L) + " — " + parseText(x.text).body.replace(/\n/g, " — ")).join("\n"));
  }
  if (cmd === "/ally" || cmd === "/alliance") {   // вкладка «Альянс» в Telegram
    await allyMenu(env, m.chat.id, L);
    return sendAlly(env, m.chat.id, L === "en" ? "🛡 Alliance: member list, your card, RoW plan and notifications. The same data as on the site." : "🛡 Альянс: участники, ваша карточка, план RoW и уведомления. Те же данные, что на сайте.", L);
  }
  if (cmd === "/start") { try { await allyMenu(env, m.chat.id, L); } catch (e) {} return send(env, m.chat.id, T.hi + (usr ? T.linked : "") + T.help); }
  return send(env, m.chat.id, T.help);
}

// ---------- рассылка (по cron) ----------
async function allyDefaults(env) {   // один раз: кнопка «Альянс» в меню всех чатов бота и команда /ally в списке
  try {
    await ensureSchema(env);
    if (await env.DB.prepare("SELECT 1 AS x FROM profiles WHERE uid = ?").bind("!allymenu2").first()) return;
    const a = await tg(env, "setChatMenuButton", { menu_button: { type: "web_app", text: "Альянс", web_app: { url: allyUrl(env) } } });
    const c = await tg(env, "setMyCommands", { commands: [{ command: "ally", description: "альянс: участники, карточка, план RoW" }, { command: "list", description: "ближайшие напоминания" }, { command: "help", description: "как подключить" }, { command: "stop", description: "удалить мои данные" }] });
    const e = await tg(env, "setMyCommands", { language_code: "en", commands: [{ command: "ally", description: "alliance: members, your card, RoW plan" }, { command: "list", description: "upcoming reminders" }, { command: "help", description: "how to connect" }, { command: "stop", description: "delete my data" }] });
    if (a.ok && c.ok) await db.putProfile(env, "!allymenu2", JSON.stringify({ a: a.ok, c: c.ok, e: e.ok }), 1, nowOf(env));
  } catch (e) { /* попробуем при следующем запуске */ }
}
async function tick(env) {
  const now = nowOf(env);
  await allyDefaults(env);
  const due = ((await env.DB.prepare("SELECT uid, key, at, text FROM items WHERE sent = 0 AND at <= ? ORDER BY at LIMIT 100").bind(now).all()).results) || [];
  let sent = 0, failed = 0;
  for (const it of due) {
    const mark = () => env.DB.prepare("UPDATE items SET sent = 1, sent_at = ? WHERE uid = ? AND key = ?").bind(now, it.uid, it.key).run();
    if (now - it.at > 3600000) { await mark(); continue; }   // слишком поздно — не шлём
    const late = now - it.at > 180000;
    const L = await getLang(env, it.uid), T = TXT[L];
    const chat = await chatOf(env, it.uid); if (!chat) { await mark(); continue; }   // аккаунт без Telegram — напоминания в Telegram не уходят
    const r = await sendNote(env, chat, it.text + (late ? T.late + leftTxt(now - it.at, L) + ")" : ""), L);
    if (r.ok) { await mark(); sent++; }
    else if (r.code === 403 || r.code === 400) { await mark(); failed++; if (r.code === 403) await env.DB.prepare("UPDATE users SET blocked = 1 WHERE uid = ?").bind(it.uid).run(); }
    else failed++;
  }
  await env.DB.prepare("DELETE FROM items WHERE sent = 1 AND COALESCE(sent_at, at) < ?").bind(now - 2 * 86400000).run();
  try { await ensureSchema(env); await env.DB.prepare("DELETE FROM logins WHERE at < ?").bind(now - 86400000).run(); } catch (e) {}
  return { sent: sent, failed: failed };
}


// ---------- рассылка от владельца (ADMIN_UID) ----------
const BC_BATCH = 15;   // получателей за один запрос (лимит подзапросов Cloudflare)
async function tgx(env, method, body, form) {
  const base = env.TG_API || "https://api.telegram.org";
  const r = await fetch(base + "/bot" + env.BOT_TOKEN + "/" + method, form ? { method: "POST", body: form } : { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
  let j = {}; try { j = await r.json(); } catch (e) {}
  return { ok: !!j.ok, code: j.error_code || r.status, wait: (j.parameters && j.parameters.retry_after) || 0, j: j };
}
function dataUrlBlob(u) {
  const m = /^data:(image\/(?:jpeg|png|webp));base64,([A-Za-z0-9+\/=]+)$/.exec(String(u || ""));
  return m ? new Blob([b64bytes(m[2])], { type: m[1] }) : null;
}
// одному получателю: [фото + подпись] и/или текст, кнопка-ссылка — к последнему сообщению
async function sendBroadcast(env, chat, p, st) {
  const markup = p.btn ? { inline_keyboard: [[{ text: p.btn.label, url: p.btn.url }]] } : undefined;
  const hasPhoto = !!(st.fid || st.blob);
  const capOk = hasPhoto && p.text.length <= 1024;
  let r = { ok: true, code: 200 };
  if (hasPhoto) {
    if (st.fid) r = await tgx(env, "sendPhoto", { chat_id: Number(chat), photo: st.fid, caption: capOk ? p.text : undefined, reply_markup: capOk ? markup : undefined });
    else {
      const fd = new FormData(); fd.append("chat_id", String(Number(chat))); if (capOk) { fd.append("caption", p.text); if (markup) fd.append("reply_markup", JSON.stringify(markup)); }
      fd.append("photo", st.blob, "photo.jpg");
      r = await tgx(env, "sendPhoto", null, fd);
      const ph = r.ok && r.j.result && r.j.result.photo; if (ph && ph.length) st.fid = ph[ph.length - 1].file_id;
    }
    if (!r.ok) return r;
    if (capOk || !p.text) return r;
  }
  return tgx(env, "sendMessage", { chat_id: Number(chat), text: p.text || "\u2063", reply_markup: markup, disable_web_page_preview: hasPhoto });
}
async function adminAction(env, uid, body, now) {
  const a = String(body.a || "");
  if (a === "check") return { code: 200, j: { admin: !!env.ADMIN_UID && String(env.ADMIN_UID) === uid } };
  if (!env.ADMIN_UID || String(env.ADMIN_UID) !== uid) return { code: 403, j: { error: "Нет доступа" } };
  if (a === "count") return { code: 200, j: { total: ((await env.DB.prepare("SELECT COUNT(*) AS n FROM users WHERE blocked = 0").first()) || {}).n || 0 } };
  if (a !== "send") return { code: 400, j: { error: "bad action" } };
  const text = String(body.text || "").trim().slice(0, 3500);
  let btn = null;
  if (body.btn && (body.btn.url || body.btn.label)) {
    const url = String(body.btn.url || "").trim();
    if (!/^https?:\/\/[^\s]+$/i.test(url)) return { code: 400, j: { error: "Ссылка должна начинаться с http:// или https://" } };
    btn = { url: url.slice(0, 500), label: String(body.btn.label || "Открыть").trim().slice(0, 40) || "Открыть" };
  }
  const blob = body.photo ? dataUrlBlob(body.photo) : null;
  if (body.photo && !blob) return { code: 400, j: { error: "Картинка не распознана (нужен JPEG, PNG или WEBP)" } };
  if (blob && blob.size > 4000000) return { code: 413, j: { error: "Картинка слишком большая" } };
  const fidIn = /^[A-Za-z0-9_-]{20,200}$/.test(String(body.fid || "")) ? String(body.fid) : "";
  if (!text && !blob && !fidIn) return { code: 400, j: { error: "Пустое сообщение" } };
  const p = { text: text, btn: btn }, st = { fid: fidIn, blob: fidIn ? null : blob };
  if (body.test) {
    const r = await sendBroadcast(env, uid, p, st);
    return { code: 200, j: { ok: r.ok, fid: st.fid || "", error: r.ok ? "" : "Telegram не принял сообщение (код " + r.code + ")" } };
  }
  const after = /^\d{1,20}$/.test(String(body.after || "")) ? String(body.after) : "";
  const rows = ((await env.DB.prepare("SELECT uid FROM users WHERE blocked = 0 AND uid > ? ORDER BY uid LIMIT ?").bind(after, BC_BATCH).all()).results) || [];
  let ok = 0, failed = 0, blocked = 0, last = after;
  for (let i = 0; i < rows.length; i++) {
    const chat = await chatOf(env, rows[i].uid); if (!chat) { last = rows[i].uid; continue; }
    const r = await sendBroadcast(env, chat, p, st);
    if (r.ok) ok++;
    else if (r.code === 429) return { code: 200, j: { sent: ok, failed: failed, blocked: blocked, after: last, done: false, fid: st.fid || "", wait: r.wait || 3 } };
    else { failed++; if (r.code === 403) { blocked++; await env.DB.prepare("UPDATE users SET blocked = 1 WHERE uid = ?").bind(rows[i].uid).run(); } }
    last = rows[i].uid;
  }
  return { code: 200, j: { sent: ok, failed: failed, blocked: blocked, after: last, done: rows.length < BC_BATCH, fid: st.fid || "" } };
}

// ---------- HTTP ----------
export default {
  async fetch(req, env) {
    const cors = { "access-control-allow-origin": env.ALLOWED_ORIGIN || "*", "access-control-allow-headers": "authorization,content-type", "access-control-allow-methods": "GET,POST,OPTIONS", "access-control-max-age": "86400" };
    const reply = (code, obj) => new Response(JSON.stringify(obj === undefined ? {} : obj), { status: code, headers: Object.assign({ "content-type": "application/json; charset=utf-8" }, cors) });
    try {
      if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: cors });
      const url = new URL(req.url), now = nowOf(env);
      const SECRET = env.SECRET || "", TOKEN = env.BOT_TOKEN || "";
      let name = String(url.searchParams.get("r") || "").replace(/[^a-z]/g, "");
      if (!name) name = url.pathname.replace(/\/+$/, "").split("/").pop();
      let body = {}; const raw = req.method === "POST" ? await req.text() : "";
      if (raw) { try { body = JSON.parse(raw); } catch (e) { return reply(400, { error: "bad json" }); } }
      const whSecret = async () => (await hmacHex(SECRET, "webhook")).slice(0, 32);

      if (name === "setup") {   // одноразовая настройка: <адрес>?r=setup&key=<SECRET>
        if (!SECRET || !eq(url.searchParams.get("key") || "", SECRET)) return reply(403, { error: "forbidden" });
        if (!env.PUBLIC_URL) return reply(400, { error: "Не задана переменная PUBLIC_URL (адрес воркера)" });
        await env.DB.batch(SCHEMA.map((s) => env.DB.prepare(s)));
        const w = await tg(env, "setWebhook", { url: env.PUBLIC_URL.replace(/\/+$/, "") + "/?r=tg", secret_token: await whSecret(), allowed_updates: ["message"], drop_pending_updates: true });
        const c = await tg(env, "setMyCommands", { commands: [{ command: "list", description: "ближайшие напоминания" }, { command: "help", description: "как подключить" }, { command: "stop", description: "удалить мои данные" }] });
        return reply(200, { tables: "готово", webhook: w, commands: c });
      }
      if (name === "tick") {   // ручной запуск рассылки: <адрес>/?r=tick&key=<SECRET> — для проверки
        if (!SECRET || !eq(url.searchParams.get("key") || "", SECRET)) return reply(403, { error: "forbidden" });
        const pending = ((await env.DB.prepare("SELECT COUNT(*) AS n FROM items WHERE sent = 0").first()) || {}).n;
        const res = await tick(env);
        return reply(200, { result: res, waiting_in_db: pending, server_time: new Date(now).toISOString() });
      }
      if (name === "tg") {
        if (!eq(req.headers.get("x-telegram-bot-api-secret-token") || "", await whSecret())) return reply(403, { error: "forbidden" });
        await onUpdate(env, body); return reply(200, { ok: true });
      }
      if (name === "trdiag") {   // проверка автоперевода: <адрес>/?r=trdiag — какие переводчики отвечают с этого сервера
        const log = {}; await trOne(env, "Hello, where are you going?", "ru", log); return reply(200, log);
      }
      if (name === "lpoll") {   // сайт спрашивает: нажал ли человек «Старт» у бота
        await ensureSchema(env);
        const code = String(body.code || "").toLowerCase();
        if (!/^[a-f0-9]{24,64}$/.test(code)) return reply(400, { error: "bad code" });
        const row = await env.DB.prepare("SELECT uid, name, at FROM logins WHERE code = ?").bind(code).first();
        if (!row || now - row.at > 900000) return reply(200, { pending: true });
        await env.DB.prepare("DELETE FROM logins WHERE code = ?").bind(code).run();
        return reply(200, { token: await mkToken(env, row.uid, now), uid: row.uid, name: row.name, botOk: true, via: "tg" });
      }
      if (name === "gauth") {   // вход через Google: аккаунт по привязке g:<sub> или новый аккаунт g<sub>
        await ensureSchema(env);
        const g = await googleVerify(env, body.credential); if (!g) return reply(401, { error: "Вход через Google не подтверждён" });
        const idr = await env.DB.prepare("SELECT uid FROM idents WHERE ext = ?").bind("g:" + g.sub).first();
        const uid = await resolveAcct(env, "g:" + g.sub, "g" + g.sub, true), old = await db.getUser(env, uid);
        await db.putUser(env, { uid, name: (old && old.name) || g.name, created: (old && old.created) || now, blocked: false });
        if (!idr) await env.DB.prepare("INSERT INTO idents (ext, uid, at) VALUES (?, ?, ?)").bind("g:" + g.sub, uid, now).run();
        await setLang(env, uid, body.lang);
        return reply(200, { token: await mkToken(env, uid, now), uid, name: (old && old.name) || g.name, via: "google" });
      }
      if (name === "auth") {
        const d = body;
        if (!d || !d.hash || !d.id || !d.auth_date) return reply(401, { error: "Вход не подтверждён Telegram" });
        const lines = Object.keys(d).filter((k) => k !== "hash" && k !== "lang").sort().map((k) => k + "=" + d[k]).join("\n");
        const key = await crypto.subtle.digest("SHA-256", enc.encode(TOKEN));
        if (!eq(await hmacHex(key, lines), String(d.hash)) || now / 1000 - Number(d.auth_date) >= 86400) return reply(401, { error: "Вход не подтверждён Telegram" });
        await ensureSchema(env);
        const uid = await acctOfTg(env, String(d.id), true), old = await db.getUser(env, uid), nm = (old && old.name) || String(d.first_name || d.username || "игрок").slice(0, 60);
        await db.putUser(env, { uid: uid, name: nm, created: (old && old.created) || now, blocked: false });
        await setLang(env, uid, d.lang);
        const r = await send(env, uid, TXT[await getLang(env, uid)].ok);
        return reply(200, { token: await mkToken(env, uid, now), uid: uid, name: nm, botOk: r.ok });
      }
      if (name === "tgwa") {   // вход из мини-приложения Telegram: подпись initData (правила Telegram) → тот же аккаунт, что на сайте
        const p = new URLSearchParams(String(body.initData || "")), hash = p.get("hash") || "";
        if (!hash || !TOKEN) return reply(401, { error: "Откройте из Telegram" });
        const dcs = [...p.keys()].filter((k) => k !== "hash").sort().map((k) => k + "=" + p.get(k)).join("\n");
        const sk = await crypto.subtle.sign("HMAC", await crypto.subtle.importKey("raw", enc.encode("WebAppData"), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]), enc.encode(TOKEN));
        if (!eq(await hmacHex(sk, dcs), hash) || now / 1000 - Number(p.get("auth_date") || 0) > 7 * 86400) return reply(401, { error: "Вход не подтверждён Telegram" });
        let u = {}; try { u = JSON.parse(p.get("user") || "{}"); } catch (e) {}
        if (!u || !u.id) return reply(401, { error: "Нет данных пользователя Telegram" });
        await ensureSchema(env);
        const uid = await acctOfTg(env, String(u.id), true), old = await db.getUser(env, uid), nm = (old && old.name) || String(u.first_name || u.username || "игрок").slice(0, 60);
        await db.putUser(env, { uid: uid, name: nm, created: (old && old.created) || now, blocked: false });
        await setLang(env, uid, tgLang(u.language_code), true);
        return reply(200, { token: await mkToken(env, uid, now), uid: uid, name: nm, via: "tgwa" });
      }
      if (name === "alpush") {   // уведомление альянса от wolfich-license (подпись тем же SECRET): участнику в Telegram с кнопкой «Открыть альянс»
        const uidP = String(body.uid || ""), ts = +body.ts || 0, ru = String(body.ru || "").slice(0, 900), en = String(body.en || ru).slice(0, 900);
        if (!SECRET || Math.abs(now - ts) > 300000 || !eq(await hmacHex(SECRET, "alpush|" + uidP + "|" + ts + "|" + ru + "|" + en), String(body.sig || ""))) return reply(403, { error: "forbidden" });
        await ensureSchema(env);
        const chat = await chatOf(env, uidP); if (!chat) return reply(200, { ok: false, why: "no telegram" });
        const L2 = await getLang(env, uidP), r = await sendAlly(env, chat, L2 === "en" ? en : ru, L2);
        return reply(200, { ok: r.ok, code: r.code });
      }
      // всё остальное — только с токеном
      const m = /^(\d{1,20}|g\d{1,40})\.(\d+)\.([0-9a-f]{64})$/.exec(String(body.token || ""));
      if (!m || !eq(await hmacHex(SECRET, m[1] + "." + m[2]), m[3]) || Number(m[2]) < now) return reply(401, { error: "Нужно войти заново" });
      const uid = m[1];
      // профиль игрока (герои и расчёты) — хранится под Telegram-аккаунтом, нужен только действующий токен
      if (name === "pget" || name === "pput" || name === "pdel") {
        await ensureSchema(env);
        const cur = await db.getProfile(env, uid), curVer = cur ? cur.ver : 0;
        if (name === "pget") { let data = null; if (cur) { try { data = JSON.parse(cur.data); } catch (e) { data = null; } } return reply(200, { data: data, ver: curVer, updated: cur ? cur.updated : 0 }); }
        if (name === "pdel") { await db.delProfile(env, uid); return reply(200, { ok: true }); }
        const txt = JSON.stringify(body.data === undefined ? null : body.data);
        if (!body.data || typeof body.data !== "object" || Array.isArray(body.data)) return reply(400, { error: "Нет данных профиля" });
        if (txt.length > PROFILE_MAX) return reply(413, { error: "Профиль слишком большой" });
        if (Number(body.ver || 0) !== curVer) { let data = null; try { data = cur ? JSON.parse(cur.data) : null; } catch (e) {} return reply(409, { error: "Профиль изменён на другом устройстве", data: data, ver: curVer }); }
        await db.putProfile(env, uid, txt, curVer + 1, now);
        return reply(200, { ok: true, ver: curVer + 1 });
      }
      // напоминания целиком (для переноса между устройствами) — лежат в profiles под ключом "r"+uid
      if (name === "rget" || name === "rput") {
        await ensureSchema(env);
        const rid = "r" + uid, cur = await db.getProfile(env, rid), curVer = cur ? cur.ver : 0;
        const curData = () => { try { return cur ? JSON.parse(cur.data) : null; } catch (e) { return null; } };
        if (name === "rget") return reply(200, { data: curData(), ver: curVer });
        if (!body.data || typeof body.data !== "object" || Array.isArray(body.data)) return reply(400, { error: "Нет данных" });
        const txt = JSON.stringify(body.data);
        if (txt.length > 200000) return reply(413, { error: "Слишком много напоминаний" });
        if (Number(body.ver || 0) !== curVer) return reply(409, { error: "Изменено на другом устройстве", data: curData(), ver: curVer });
        await db.putProfile(env, rid, txt, curVer + 1, now);
        return reply(200, { ok: true, ver: curVer + 1 });
      }
      const usr = await db.getUser(env, uid);
      if (!usr) return reply(401, { error: "Профиль не найден" });
      let room = "";
      if (name === "tr") {   // автоперевод заметок и сообщений на язык устройства: { texts: [...], to: "ru" } → { list: [{ t, src }] }
        const to = String(body.to || "").toLowerCase().replace(/[^a-z-]/g, "").slice(0, 7); if (!/^[a-z]{2,3}(-[a-z]{2,4})?$/.test(to)) return reply(400, { error: "bad lang" });
        const texts = (Array.isArray(body.texts) ? body.texts : []).slice(0, 30).map((t) => String(t || "").slice(0, 600));
        await ensureSchema(env);
        const list = [];
        for (const t of texts) {
          if (!t.trim() || !/\p{L}/u.test(t)) { list.push({ t: "", src: to }); continue; }
          const h = await sha256Hex(to + "|" + t), c = await env.DB.prepare("SELECT out, src FROM trc WHERE h = ?").bind(h).first();
          if (c) { list.push({ t: c.out, src: c.src || "" }); continue; }
          const r = await trOne(env, t, to);
          if (!r) { list.push({ t: "", src: "", err: true }); continue; }
          await env.DB.prepare("INSERT OR REPLACE INTO trc (h, out, src, at) VALUES (?, ?, ?, ?)").bind(h, r.out, r.src, now).run();
          list.push({ t: r.out, src: r.src });
        }
        if (Math.random() < 0.02) await env.DB.prepare("DELETE FROM trc WHERE at < ?").bind(now - 30 * 86400000).run();
        return reply(200, { ok: true, list });
      }
      if (name === "here" || name === "chat") {   // комната планера: доступ подтверждает билет rt от wolfich-license (тот же SECRET)
        room = String(body.room || ""); if (!/^(a:[a-z0-9]{6,16}:[1-3]|p:[a-z0-9]{6,16})$/.test(room)) return reply(400, { error: "bad room" });
        const tk = /^(\d+)\.([01])\.([0-9a-f]{64})$/.exec(String(body.rt || ""));   // билет: срок.ред.подпись (ред=1 — редактор карты)
        if (!tk || +tk[1] < now || !eq(await hmacHex(SECRET, room + "|" + uid + "|" + tk[1] + "|" + tk[2]), tk[3])) return reply(403, { error: "нет доступа к карте", rt: true });
        var roomEd = tk[2] === "1";
      }
      if (name === "chat") {   // чат карты: { text? } — отправить; { since } — новые сообщения после id
        await ensureSchema(env);
        const nm = String(body.name || usr.name || "").replace(/[\u0000-\u001f]/g, " ").slice(0, 32);
        const text = String(body.text || "").replace(/[\u0000-\u0009\u000b-\u001f]/g, " ").trim().slice(0, 500);
        if (body.clear) {   // очистить чат: только редакторы карты; у всех остальных список сбросится по служебной записи
          if (!roomEd) return reply(403, { error: "очищать чат могут офицеры и редакторы карты" });
          await env.DB.prepare("DELETE FROM chat WHERE room = ?").bind(room).run();
          await env.DB.prepare("INSERT INTO chat (room, uid, name, text, at) VALUES (?, '!', ?, '', ?)").bind(room, nm, now).run();
        } else if (body.upd) {   // редактор сохранил карту: служебная запись — у остальных карта перезагрузится
          if (!roomEd) return reply(403, { error: "сохранять карту могут офицеры и редакторы" });
          await env.DB.prepare("INSERT INTO chat (room, uid, name, text, at) VALUES (?, '!', ?, ?, ?)").bind(room, nm, "upd:" + String(body.pl || "A").replace(/[^ABC]/g, "").slice(0, 1), now).run();
        } else if (text) {
          const last = await env.DB.prepare("SELECT at FROM chat WHERE room = ? AND uid = ? ORDER BY id DESC LIMIT 1").bind(room, uid).first();
          if (last && now - last.at < 700) return reply(429, { error: "слишком часто" });
          await env.DB.prepare("INSERT INTO chat (room, uid, name, text, at) VALUES (?, ?, ?, ?, ?)").bind(room, uid, nm, text, now).run();
          if (Math.random() < 0.05) await env.DB.prepare("DELETE FROM chat WHERE at < ?").bind(now - 7 * 86400000).run();
        }
        const since = Math.max(0, Math.floor(+body.since || 0));
        const rows = ((await env.DB.prepare("SELECT id, uid, name, text, at FROM chat WHERE room = ? AND id > ? AND at > ? ORDER BY id DESC LIMIT 60").bind(room, since, now - 7 * 86400000).all()).results) || [];
        return reply(200, { ok: true, list: rows.reverse().map((x) => (x.uid === "!" ? { id: x.id, sys: String(x.text || "").slice(0, 4) === "upd:" ? "upd" : "clr", pl: String(x.text || "").slice(4) || undefined, name: x.name, at: x.at, me: false } : { id: x.id, name: x.name, text: x.text, at: x.at, me: x.uid === uid })) });
      }
      if (name === "here") {   // планер: «я на карте» → список тех, кто на ней последние ~100 с
        await ensureSchema(env);
        if (body.leave) await env.DB.prepare("DELETE FROM presence WHERE room = ? AND uid = ?").bind(room, uid).run();
        else await env.DB.prepare("INSERT OR REPLACE INTO presence (room, uid, name, at) VALUES (?, ?, ?, ?)").bind(room, uid, String(body.name || usr.name || "").replace(/[\u0000-\u001f]/g, " ").slice(0, 32), now).run();
        if (Math.random() < 0.05) await env.DB.prepare("DELETE FROM presence WHERE at < ?").bind(now - 600000).run();
        const rows = ((await env.DB.prepare("SELECT uid, name FROM presence WHERE room = ? AND at > ? ORDER BY name").bind(room, now - 100000).all()).results) || [];
        return reply(200, { ok: true, list: rows.map((x) => ({ name: x.name, me: x.uid === uid })) });
      }
      if (name === "acct") return reply(200, { uid, name: usr.name, idents: await identsOf(env, uid) });   // аккаунт: имя и способы входа
      if (name === "glink") {   // привязать Google к открытому аккаунту
        const g = await googleVerify(env, body.credential); if (!g) return reply(401, { error: "Вход через Google не подтверждён" });
        const cur = await env.DB.prepare("SELECT uid FROM idents WHERE ext = ?").bind("g:" + g.sub).first();
        if (cur && cur.uid !== uid && cur.uid !== "!") {
          if (!body.force) { const ou = await db.getUser(env, cur.uid); return reply(409, { conflict: true, name: (ou && ou.name) || "", error: "Этот Google-аккаунт уже зарегистрирован на сайте отдельно." }); }
          await moveInto(env, cur.uid, uid);   // перенос: этот Google теперь входит в текущий аккаунт
        }
        await env.DB.prepare("INSERT OR REPLACE INTO idents (ext, uid, at) VALUES (?, ?, ?)").bind("g:" + g.sub, uid, now).run();
        return reply(200, { ok: true, idents: await identsOf(env, uid) });
      }
      if (name === "tlreq") {   // привязать Telegram: код для t.me/<бот>?start=link_<код>
        const code = String(body.code || "").toLowerCase(); if (!/^[a-f0-9]{24,64}$/.test(code)) return reply(400, { error: "bad code" });
        await env.DB.prepare("INSERT OR REPLACE INTO links (code, uid, st, at) VALUES (?, ?, NULL, ?)").bind(code, uid, now).run();
        await env.DB.prepare("DELETE FROM links WHERE at < ?").bind(now - 86400000).run();
        return reply(200, { ok: true });
      }
      if (name === "tlpoll") {
        const row = await env.DB.prepare("SELECT uid, st FROM links WHERE code = ?").bind(String(body.code || "").toLowerCase()).first();
        if (!row || row.uid !== uid) return reply(200, { pending: true });
        if (!row.st) return reply(200, { pending: true });
        if (row.st.slice(0, 5) === "conf:") return reply(200, { conflict: true, name: row.st.split(":").slice(2).join(":") });
        if (row.st !== "ok") return reply(200, { error: "Не получилось привязать Telegram" });
        return reply(200, { ok: true, idents: await identsOf(env, uid) });
      }
      if (name === "tlmove") {   // подтверждён перенос Telegram (у которого был свой аккаунт) в текущий аккаунт
        const row = await env.DB.prepare("SELECT uid, st, at FROM links WHERE code = ?").bind(String(body.code || "").toLowerCase()).first();
        if (!row || row.uid !== uid || !row.st || row.st.slice(0, 5) !== "conf:" || now - row.at > 1800000) return reply(400, { error: "Ссылка для привязки устарела — нажмите «Привязать Telegram» ещё раз" });
        const tgid = row.st.split(":")[1], cur = await env.DB.prepare("SELECT uid FROM idents WHERE ext = ?").bind("t:" + tgid).first();
        await moveInto(env, cur ? (cur.uid === "!" ? "" : cur.uid) : tgid, uid);
        await env.DB.prepare("INSERT OR REPLACE INTO idents (ext, uid, at) VALUES (?, ?, ?)").bind("t:" + tgid, uid, now).run();
        await env.DB.prepare("UPDATE links SET st = 'ok' WHERE code = ?").bind(row.code || String(body.code || "").toLowerCase()).run();
        return reply(200, { ok: true, idents: await identsOf(env, uid) });
      }
      if (name === "unl") {   // отвязать способ входа (если остаётся другой); следующий вход им создаст новый аккаунт
        const what = body.what === "google" ? "google" : "tg", I = await identsOf(env, uid);
        if (!(what === "tg" ? I.google : I.tg)) return reply(400, { error: "Нельзя отвязать единственный способ входа" });
        if (what === "google") await env.DB.prepare("UPDATE idents SET uid = '!', at = ? WHERE uid = ? AND ext LIKE 'g:%'").bind(now, uid).run();
        else {
          await env.DB.prepare("UPDATE idents SET uid = '!', at = ? WHERE uid = ? AND ext LIKE 't:%'").bind(now, uid).run();
          if (/^\d+$/.test(uid)) await env.DB.prepare("INSERT OR REPLACE INTO idents (ext, uid, at) VALUES (?, '!', ?)").bind("t:" + uid, now).run();
        }
        return reply(200, { ok: true, idents: await identsOf(env, uid) });
      }
      if (name === "adm") { const ar = await adminAction(env, uid, body, now); return reply(ar.code, ar.j); }
      if (name === "me") { const its = await db.listItems(env, uid); return reply(200, { uid: uid, name: usr.name, blocked: !!usr.blocked, pending: its.filter((x) => !x.sent).length }); }
      if (name === "test") { await setLang(env, uid, body.lang); const r = await send(env, (await chatOf(env, uid)) || uid, TXT[await getLang(env, uid)].test); return reply(200, { ok: r.ok, error: r.ok ? "" : "Откройте бота в Telegram и нажмите «Старт»" }); }
      if (name === "unlink") { await db.deleteUser(env, uid); await db.delProfile(env, "r" + uid); await db.delProfile(env, "l" + uid); return reply(200, { ok: true }); }
      if (name === "sync") {
        await setLang(env, uid, body.lang);
        const inc = Array.isArray(body.items) ? body.items.slice(0, 100) : [];
        const have = new Map((await db.listItems(env, uid)).map((x) => [x.key, x])), keep = new Set();
        for (const x of inc) {
          const key = String(x.key || "").slice(0, 60), at = Math.round(Number(x.at)), text = String(x.text || "").slice(0, 200);
          if (!key || !isFinite(at) || !text) continue;
          keep.add(key);
          const ex = have.get(key);
          if (ex && ex.at === at && ex.text === text) continue;
          await db.putItem(env, uid, { key: key, at: at, text: text, sent: ex && ex.at === at ? !!ex.sent : false });
        }
        for (const k of have.keys()) if (!keep.has(k)) await db.delItem(env, uid, k);
        return reply(200, { ok: true, count: keep.size });
      }
      return reply(404, { error: "not found" });
    } catch (e) {
      console.error("handler error", e && e.stack || e);
      return new Response(JSON.stringify({ error: "server error" }), { status: 500, headers: { "content-type": "application/json", "access-control-allow-origin": env.ALLOWED_ORIGIN || "*" } });
    }
  },
  async scheduled(event, env, ctx) { ctx.waitUntil(tick(env)); },
  tick: tick,
};
